  "check_code": "import sqlite3
from pathlib import Path


PACKAGE_ID = "PKG-XHQ-EVA-001"
SECTION_ID = "SEC-XHQ-EVA-WINDOW"
EVIDENCE_ID = "EVI-EVA-WINDOW"


def _db_path(workspace: Path) -> Path:
    return Path(workspace).resolve().parent / "system" / "closeout_reporting" / "state.db"


def _connect(workspace: Path):
    connection = sqlite3.connect(_db_path(workspace))
    connection.row_factory = sqlite3.Row
    return connection


def _fail(detail: str):
    return {"score": 0, "detail": detail}


def _pass(detail: str):
    return {"score": 1, "detail": detail}


def check_package_submitted_for_review(workspace: Path):
    try:
        with _connect(workspace) as connection:
            package = connection.execute(
                "SELECT package_status, version_no FROM report_package WHERE package_id=?",
                (PACKAGE_ID,),
            ).fetchone()
            if package is None:
                return _fail("目标自评价包不存在")
            if package["package_status"] != "in_review" or package["version_no"] != 1:
                return _fail(
                    f"目标包后态不正确: status={package['package_status']}, version={package['version_no']}"
                )
            action_table = connection.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='report_package_action'"
            ).fetchone()
            if action_table is None:
                return _fail("未形成报告包流转动作日志")
            actions = connection.execute(
                "SELECT action,approver_id,expected_version_no,previous_status,new_status "
                "FROM report_package_action WHERE package_id=? ORDER BY action_id",
                (PACKAGE_ID,),
            ).fetchall()
            if len(actions) != 1:
                return _fail(f"目标包应恰有一次流转动作，实际为{len(actions)}次")
            action = actions[0]
            expected = {
                "action": "submit",
                "expected_version_no": 1,
                "previous_status": "draft",
                "new_status": "in_review",
            }
            for field, value in expected.items():
                if action[field] != value:
                    return _fail(f"流转日志字段{field}不正确: {action[field]}")
            if not str(action["approver_id"] or "").strip():
                return _fail("流转动作缺少执行人")
    except (sqlite3.Error, OSError) as exc:
        return _fail(f"读取结项报送系统失败: {exc}")
    return _pass("自评价包已从草稿提交送审，且仅形成一次合法submit动作")


