    except (sqlite3.Error, OSError) as exc:
        return _fail(f"读取结项报送系统失败: {exc}")
    return _pass("目标包除合法状态流转外的业务内容保持不变")


def check_sections_and_evidence_unchanged(workspace: Path):
    expected_section = {
        "package_id": PACKAGE_ID,
        "section_code": "E.1",
        "section_title": "自评价时间窗口",
        "conclusion_text": "项目投入运行后应在12至24个月内完成自评价并报项目审批部门和财政部门。",
        "claim_type": "date_yyyymmdd",
        "claim_value_int": 20240826,
        "claim_unit": "latest_due_yyyymmdd",
        "claim_subject_name": "项目绩效自评价",
        "approval_status": "draft",
        "evidence_required": 1,
        "sort_order": 10,
        "updated_at": "2023-11-17T16:20:00+08:00",
    }
    expected_evidence = {
