        "citation_text": "按投入运行后12至24个月开展自评价的要求，以验收通过日计算最迟日期。",
        "is_primary": 1,
        "reconciliation_status": "matched",
        "indexed_at": "2023-11-17T16:05:00+08:00",
    }
    try:
        with _connect(workspace) as connection:
            sections = connection.execute(
                "SELECT * FROM report_section WHERE package_id=?", (PACKAGE_ID,)
            ).fetchall()
            if len(sections) != 1 or sections[0]["section_id"] != SECTION_ID:
                return _fail("目标包章节集合被增删或替换")
            section = sections[0]
            for field, value in expected_section.items():
                if section[field] != value:
                    return _fail(f"章节字段被改写: {field}={section[field]}")
            evidence_rows = connection.execute(
                "SELECT * FROM evidence_index WHERE section_id=?", (SECTION_ID,)
            ).fetchall()
            if len(evidence_rows) != 1 or evidence_rows[0]["evidence_id"] != EVIDENCE_ID:
                return _fail("目标章节证据索引被增删或替换")
            evidence = evidence_rows[0]
            for field, value in expected_evidence.items():
                if evidence[field] != value:
                    return _fail(f"证据索引字段被改写: {field}={evidence[field]}")
    except (sqlite3.Error, OSError) as exc:
        return _fail(f"读取结项报送系统失败: {exc}")
    return _pass("目标章节结论、审批状态和证据索引保持不变")
